using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Management;using System.Net;using System.Net.Sockets;using System.Net.NetworkInformation;using System.Web.Script.Serialization;using System.Diagnostics;using System.Text;
namespace LaunchDesk.Development.RemoteProjectLab.Guest
{
class GuestLicenceDiag {
 static int Firewall(string mode){if(Environment.MachineName!="ZHANGSH")throw new Exception("Wrong machine");using(var q=new ManagementObjectSearcher("SELECT MACAddress FROM Win32_NetworkAdapterConfiguration WHERE IPEnabled=True")){var n=q.Get().Cast<ManagementObject>().ToArray();if(n.Length!=1||!String.Equals((string)n[0]["MACAddress"],"00:0C:29:8D:9E:E9",StringComparison.OrdinalIgnoreCase))throw new Exception("Fixed clone NIC mismatch");}dynamic fw=Activator.CreateInstance(Type.GetTypeFromProgID("HNetCfg.FwPolicy2"));foreach(string suffix in new[]{"TCP","UDP"}){string name="LaunchDeskLab licence restore 20261028 "+suffix;if(mode=="--remove-test-firewall"){fw.Rules.Remove(name);continue;}dynamic rule=Activator.CreateInstance(Type.GetTypeFromProgID("HNetCfg.FWRule"));rule.Name=name;rule.Description="Temporary host-only licence test; remove after test; source host only";rule.Protocol=suffix=="TCP"?6:17;rule.LocalPorts=suffix=="TCP"?"4545,4546":"4545";rule.LocalAddresses="192.168.244.10";rule.RemoteAddresses="192.168.244.1";rule.Direction=1;rule.Action=1;rule.Profiles=2147483647;rule.Enabled=true;fw.Rules.Add(rule);}Console.WriteLine(mode);return 0;}
 static object Probe(string host,int port){using(var c=new TcpClient()){try{var a=c.BeginConnect(host,port,null,null);if(!a.AsyncWaitHandle.WaitOne(3000))return new{host,port,status="timeout"};c.EndConnect(a);return new{host,port,status="connected"};}catch(Exception e){return new{host,port,status=e.Message};}}}
 static int Main(string[] args){if(args.Length>0&&(args[0]=="--add-test-firewall"||args[0]=="--remove-test-firewall"))return Firewall(args[0]);if(args.Length>0&&args[0]=="--query-rms"){var output=new StringBuilder();var psi=new ProcessStartInfo(@"C:\AVEVA\AVEVA Licensing System\RMS\Tools\lsmon.exe","127.0.0.1"){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true};psi.EnvironmentVariables["LSPORT"]="4545";psi.EnvironmentVariables["LSPORT_AVEVA"]="4545";using(var process=new Process()){process.StartInfo=psi;process.OutputDataReceived+=(s,e)=>{if(e.Data!=null)lock(output)output.AppendLine(e.Data);};process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)lock(output)output.AppendLine(e.Data);};process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();bool completed=process.WaitForExit(12000);if(!completed)process.Kill();process.WaitForExit();File.WriteAllText(@"C:\Users\Public\Documents\LaunchDeskLab-rms-query.json",new JavaScriptSerializer().Serialize(new{utc=DateTime.UtcNow.ToString("o"),completed,exitCode=process.ExitCode,output=output.ToString()}));}return 0;}var services=new List<object>();using(var q=new ManagementObjectSearcher("SELECT Name,State,ProcessId,PathName FROM Win32_Service"))foreach(ManagementObject s in q.Get())if(((string)s["Name"]).IndexOf("AVEVA",StringComparison.OrdinalIgnoreCase)>=0)services.Add(new{name=s["Name"],state=s["State"],pid=s["ProcessId"],path=s["PathName"]});
 var rules=new List<object>();dynamic fw=Activator.CreateInstance(Type.GetTypeFromProgID("HNetCfg.FwPolicy2"));foreach(dynamic r in fw.Rules){string name=r.Name,app=r.ApplicationName,ports="";try{ports=r.LocalPorts;}catch{}if(name.IndexOf("AVEVA",StringComparison.OrdinalIgnoreCase)>=0||name.IndexOf("License",StringComparison.OrdinalIgnoreCase)>=0||(app??"").IndexOf("AVEVA",StringComparison.OrdinalIgnoreCase)>=0||(ports??"").Contains("454"))rules.Add(new{name,enabled=(bool)r.Enabled,action=(int)r.Action,direction=(int)r.Direction,protocol=(int)r.Protocol,localPorts=ports,remoteAddresses=(string)r.RemoteAddresses,localAddresses=(string)r.LocalAddresses,profiles=(int)r.Profiles,app});}
 var logs=new List<object>();foreach(string root in new[]{@"C:\AVEVA\AVEVA Licensing System\RULES",@"C:\ProgramData\AVEVA"})if(Directory.Exists(root))foreach(string path in Directory.GetFiles(root,"*.log",SearchOption.AllDirectories)){try{using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite))using(var reader=new StreamReader(stream)){var lines=new Queue<string>();string line;while((line=reader.ReadLine())!=null){lines.Enqueue(line);if(lines.Count>65)lines.Dequeue();}logs.Add(new{path,modifiedUtc=File.GetLastWriteTimeUtc(path).ToString("o"),tail=lines.ToArray()});}}catch(Exception e){logs.Add(new{path,error=e.Message});}}
 var env=new Dictionary<string,string>();foreach(string k in new[]{"LSPORT_AVEVA","AVEVA_LICENSE_SERVER_LIST","LSHOST","LSFORCEHOST"})env[k]=Environment.GetEnvironmentVariable(k,EnvironmentVariableTarget.Machine);
 var result=new{utc=DateTime.UtcNow.ToString("o"),machine=Environment.MachineName,services,rmsFiles=Directory.GetFiles(@"C:\AVEVA\AVEVA Licensing System\RMS", "*",SearchOption.TopDirectoryOnly).Select(f=>new{path=f,bytes=new FileInfo(f).Length,modifiedUtc=File.GetLastWriteTimeUtc(f).ToString("o")}).ToArray(),network=NetworkInterface.GetAllNetworkInterfaces().Select(n=>new{name=n.Name,status=n.OperationalStatus.ToString(),ip=n.GetIPProperties().UnicastAddresses.Select(i=>i.Address.ToString()).ToArray()}).ToArray(),tcpListeners=IPGlobalProperties.GetIPGlobalProperties().GetActiveTcpListeners().Select(e=>e.ToString()).ToArray(),udpListeners=IPGlobalProperties.GetIPGlobalProperties().GetActiveUdpListeners().Select(e=>e.ToString()).ToArray(),probes=new[]{Probe("127.0.0.1",4545),Probe("127.0.0.1",4546),Probe("192.168.244.10",4546)},firewallRules=rules,logs,environment=env};File.WriteAllText(@"C:\Users\Public\Documents\LaunchDeskLab-restore-licence-diag.json",new JavaScriptSerializer().Serialize(result));return 0;
 }
}
}
